import numpy as np,pandas as pd
from scipy.stats import spearmanr
def reports(counts,source,plate,study,regional,domains,diagnostics,mesh,history):
 from deliver_e13 import mdtable
 def put(name,title,text):
  (R/name).write_text('# '+title+'\n\n'+text+'\n\nEvidence: numerical V1 M2 references conditional on reconstructed geometry, assumed planar rear, isotropic linear elasticity and 100 MPa nominal X tension. Internal documentary-plate holdout is not fresh independent external or physical stress validation.\n',encoding='utf8')
 common='Source IDs, original XYZ and T0 vertex areas are unchanged. All thirteen fine M2 targets were rehashed against the accepted registry. No new ANSYS solve, FE mesh, V1 target or external prediction was executed.\n'
 table_study=mdtable(study[['model','seed','equal_plate_L2','equal_plate_MAE_MPa','equal_plate_high95_IoU','worst_plate_L2','worst_source_L2']]);neural=study[study.model=='N1_POINT_TRANSFORMER'];aggregate=neural.select_dtypes(include='number').mean().to_dict();aggregate.pop('seed',None);write(R/'07_metrics/SEED_AGGREGATE.json',dict(rule='Arithmetic mean of independently scored metrics across both seeds; no selected seed and no ensemble-field inference',metrics=aggregate));table(R/'07_metrics/SEED_AGGREGATE.csv',[dict(model='N1_POINT_TRANSFORMER',seed='METRIC_MEAN_20261021_20261022',**aggregate)])
 group_table=mdtable(pd.DataFrame(dict(plate=list('CEGHX'),sources=[3,1,5,2,2],train_sources=[10,12,8,11,11])))
 split=rows(R/'OUTER_LOPO_FOLDS.csv');splits='\n'.join(f"- {f}: train {', '.join(a['source_id'][:3] for a in split if a['fold']==f and a['role']=='train')}; held-out {', '.join(a['source_id'][:3] for a in split if a['fold']==f and a['role']=='heldout')}." for f in ['F1','F2','F3','F4','F5'])
 recipe=read(R/'MODEL_AND_TRAINING_SEAL.json');pref=read(R/'AI_RESOURCE_PREFLIGHT.json');iv=read(R/'07_metrics/INDEPENDENT_VERIFICATION.json');pairs=[]
 for p in 'CEGHX':
  b0=float(plate[(plate.plate==p)&(plate.model=='B0_CONSTANT')].L2.iloc[0]);b1=float(plate[(plate.plate==p)&(plate.model=='B1_GEOMETRY_RIDGE')].L2.iloc[0])
  for seed in ['20261021','20261022']:
   n=float(plate[(plate.plate==p)&(plate.model=='N1_POINT_TRANSFORMER')&(plate.seed.astype(str)==seed)].L2.iloc[0]);pairs.append(dict(plate=p,seed=seed,B0_L2=b0,B1_L2=b1,N1_L2=n,N1_minus_B0=n-b0,N1_minus_B1=n-b1))
 table(R/'07_metrics/PAIRED_PLATE_COMPARISONS.csv',pairs);pairtable=mdtable(pd.DataFrame(pairs));source_table=mdtable(source[['source_id','model','seed','L2','MAE_MPa','high95_IoU','worst_regional_L2','coverage']]);plate_table=mdtable(plate[['plate','model','seed','L2','MAE_MPa','high95_IoU']]);nsource=source[source.model=='N1_POINT_TRANSFORMER'];worst_source=nsource.loc[nsource.L2.idxmax()];nplate=plate[plate.model=='N1_POINT_TRANSFORMER'];worst_plate=nplate.loc[nplate.L2.idxmax()];seedmean=float(neural.equal_plate_L2.mean());seedspan=float(neural.equal_plate_L2.max()-neural.equal_plate_L2.min())
 put('HISTORICAL_TARGET_INTEGRITY.md','Historical target integrity',common+'\nE12 release: 1,561 durable files re-read with SHA-256. Thirteen target hashes and 52 native DB/RST hashes independently checked. See `00_integrity/E12_RELEASE_HASH_CHECKS.csv`, `HISTORICAL_V1_TARGET_HASHES.csv`, `00_integrity/NATIVE_PROVENANCE_HASHES.csv`. Historical reports, datasets, geometry and native results were opened read-only. The first preparation attempt completed the hash pass but failed importing its newly created module; the import-cache repair preceded every fit. `prepare_attempt1.log` preserves this non-training incident.')
 put('DOCUMENTARY_PLATE_GROUP_VERIFICATION.md','Documentary plate grouping',group_table+'\nMembership was compared with E12 CONFIRMED_PARENT_PLATE_GROUPS, itself supported by dissertation section 3.2.6/Figure 3.9: initial letter denotes plate, number specimen position. Codes are scoped to original S355MLO material. Between-plate manufacturing batch and scan-session independence remain unresolved. These five groups are not five authenticated production batches.')
 put('SOURCE_AND_TARGET_REGISTRY.md','Frozen source and target registry',common+'\n'+mdtable(pd.DataFrame(rows(R/'V1_TARGET_SUPPORT_AUDIT.csv')))+'\nAll source rows remain in prediction NPZs; scoring and exported OOF CSVs use the unchanged 34,200-point valid core for every source. Target version and all parent-datum parameters are retained in QUALIFIED13_SOURCE_REGISTRY.csv. M1 is diagnostic, not an extra training specimen.')
 put('FROZEN_FEATURE_CONTRACT.md','Nineteen-channel geometry input contract','The historical E3 schema was verified and every geometry array recomputed exactly for all thirteen sources.\n\n'+mdtable(pd.DataFrame(rows(R/'INPUT_FEATURE_CONTRACT.csv')))+'\nChannels 0–2 are source-area centered XYZ/60; 3–5 source normals; 6–8 spans/60; 9–11 global X convention; 12 front identity zero; 13 K16 Z residual in mm; 14 K16 normal deviation; 15 log1p vertex area; 16–17 global normal standard deviations; 18 duplicates visible Z span/60. This last channel is not paired rear separation. Original labels, FE IDs, reactions, displacements, hidden rear, plate identity and label-validity features are absent. Geometric region/mask fields restrict supervision/scoring only and are never passed to the network.')
 put('LEAVE_ONE_PLATE_OUT_SPLITS.md','Frozen leave-one-plate-out execution',group_table+'\n'+splits+'\nNo inner/outer error selected a model, epoch, seed, feature or inference patch. All five folds used the same sealed recipe. Historical twelve exposed test identities and all Aalborg sources were excluded from the cohort.')
 put('RESOURCE_AND_HARDWARE_PREFLIGHT.md','Resource and backend preflight','```json\n'+json.dumps(pref,indent=2)+'\n```\nCPU-only PyTorch 2.6.0 is the verified existing runtime; the GTX 1650 Ti is present but this PyTorch build has no CUDA backend. Historical S1 uses ordinary PyTorch operations, so the same architecture and 4096-point context are supported on CPU without substitution. Two CPU threads, one worker at a time; no package installation or environment change.\n\n'+f"Completed-fit training time {counts['training_s']:.3f} s; sampled worker RSS maximum {counts['peak_RSS_bytes']/1024**3:.4f} GiB; GPU allocations 0. Sampling interval 0.5 s plus epoch gates; RSS is not total-machine peak. All resource samples are in TRAINING_RESOURCE_ACCOUNTING.csv; dry-run and worker startup are separate in WORKERS.json.")
 put('TRAINING_PIPELINE_VALIDATION.md','Executed pipeline validation','```json\n'+json.dumps(read(R/'TRAINING_DRY_RUN.json'),indent=2)+'\n```\nThe dry run performed one real optimization step and is explicitly counted separately from ten scheduled fits. It used only F1 training data and checked finite forward outputs, gradients, source IDs and prescribed context/query sizes. Scheduled runs each initialized fresh, wrote immutable periodic recovery checkpoints and used final epoch 80. There was no training interruption or replacement run.')
 put('GEOMETRY_CONTEXT_SAMPLING.md','Geometry-only sampling and inference','Source-area CDF selects 4096 context entries in canonical XYZ order. K16 includes the source point, as in the verified historical implementation. Each 1/3 mm neighborhood consists of sixteen XY ring anchors snapped to the nearest original 3D point; these are not radius-ball averages. No spatial smoothing or geometry regeneration occurs.\n\nEvery source/epoch draws 512 valid core queries proportional to original area, with SeedSequence(seed, SHA256(source) prefix, epoch). Source order uses a separate seeded RNG. This is geometry/support dependent, never stress dependent. Full-source inference visits original rows in disjoint 512-query tiles; each tile uses the same full-source neighbors and 4096-point context. Stitching assigns each row exactly once, with no averaging or reference-driven patch selection. All 889,941 source rows per model/seed evaluation set are predicted; 444,600 frozen core rows are scored.')
 put('TRAINING_LOSS_WEIGHTING.md','Verified hierarchical training objective','For training source s in plate p, query points follow area probability a_i/sum(a). The raw mean squared K error is multiplied by N_train/(4*n_p). Averaging these weighted source minibatch losses across an epoch gives one quarter weight per training plate and equal source weights within each plate in expectation over point draws. No target statistic enters weights.\n\nThe historical optimizer takes one step per source minibatch; importance weighting preserves that effective batch size. This stochastic, clipped AdamW trajectory is not equivalent to a single full-batch gradient. Gradient clipping is the unchanged historical norm cap 1. Independent pretraining checks sum actual source weights to 0.25 for each training plate; runtime membership logs verify the actual sources/plates used in every minibatch.')
 for model,name in [('B0_CONSTANT','CONSTANT_BASELINE_RESULTS.md'),('B1_GEOMETRY_RIDGE','GEOMETRY_RIDGE_RESULTS.md')]:
  method='B0 averages original-area target means equally within each training plate and equally across the four training plates.' if model.startswith('B0') else 'B1 uses all nineteen permitted geometry channels; weighted training-only mean/std scaling; intercept unpenalized; alpha=1 in weighted-mean squared K plus alpha times coefficient squared norm. No alpha search. Source-specific geometry normalization is the historical inference-available rule. Constant channels receive scale 1.'
  put(name,model+' held-out results',method+'\n\n'+mdtable(study[study.model==model])+'\n'+mdtable(source[source.model==model][['source_id','L2','MAE_MPa','high95_IoU']]))
 put('POINT_TRANSFORMER_ARCHITECTURE.md','Historical S1 architecture reused without weights','The actual historical E3 `SurfacePT(multiscale=True)` and `PointTransformerStress` sources were hashed and copied. Width 24, one vector-attention residual block, three learned scale logits, 4096-source context mean, MLP decoder: 7,228 parameters. No pretrained checkpoint was loaded. All folded models begin from torch.manual_seed after creating a new model; identical seeds intentionally reproduce the same initial parameter digest across folds, without weight transfer.\n\nArchitecture SHA-256: '+sha(R/'src/model_e3.py')+'\nBase class SHA-256: '+sha(R/'src/base_arch.py'))
 put('POINT_TRANSFORMER_TRAINING.md','Ten fresh neural fits','```json\n'+json.dumps(recipe,indent=2)+'\n```\n\n'+mdtable(pd.DataFrame(rows(R/'NEURAL_RUN_REGISTRY.csv'))[['fold','seed','epochs','steps','training_s','parameters','status']])+'\nThere is no held-out best checkpoint. The final epoch is fixed before training. Periodic checkpoints are recovery records, not candidates selected by outcome.')
 put('FOLD_SPECIFIC_RESULTS.md','All five held-out plate outcomes',plate_table+'\n'+pairtable)
 put('SEED_VARIABILITY.md','Prespecified two-seed interpretation',table_study+f'\nThe arithmetic mean of the two separately scored equal-plate L2 values is {seedmean:.9f}; observed seed span {seedspan:.9f}. This is a metric aggregate, not a new ensemble prediction. Both seeds are retained and neither is selected.\n\n'+mdtable(pd.DataFrame([aggregate])))
 put('SOURCE_LEVEL_PREDICTION_METRICS.md','All held-out source metrics',source_table+'\nFull signed bias, RMSE, R², means, maxima, Q95 errors, High95 precision/recall/centroid and worst-region errors are in SOURCE_LEVEL_METRICS.csv. Undefined R² would be null; no epsilon-based finite replacement is used.')
 put('PLATE_LEVEL_PREDICTION_METRICS.md','Plate-level primary interpretation',plate_table+'\n'+table_study+'\nPrimary normalized L2 is averaged across sources within each plate and then equally across five plates. Equal-source and pooled point-area L2 are separate descriptive columns. Millions of points do not create independent experimental units. Five plate values give mean/median/min/max and paired differences, without a formal significance claim or pointwise confidence interval.')
 put('HIGH95_SPATIAL_LOCALIZATION.md','High-stress localization','Each field independently uses Q95 from stable sorted, original-area cumulative weights with linear interpolation. Masks use field>=its own Q95; ties can produce more than 5% area. A constant predictor therefore selects its whole core, which correctly yields poor localization specificity. Reference masks are used only after inference.\n\n'+mdtable(source[['source_id','model','seed','high95_IoU','high95_precision','high95_recall','high95_centroid_distance_mm']])+'\nFigures 24–26 distinguish false-negative, false-positive and shared high-stress areas. Figures use every third core row for display; metrics use all original core rows.')
 put('REGIONAL_STRESS_ERROR_ANALYSIS.md','Geometry proxy regional errors','V1 region code 0 = parent proxy, 1 = relief>=0.5 mm, 2 = adjacent projected collar<=2 mm outside relief. These are frozen geometric labels, not authenticated weld-toe positions.\n\n'+mdtable(regional[['source_id','model','seed','region','L2','MAE_MPa','bias_MPa']])+'\nHighest absolute-error coordinates and High95 false-positive/negative areas are in ERROR_DIAGNOSTICS.csv. Error-versus-height, K16 Z residual, normal variation and target magnitude bins are in 07_metrics/ERROR_DESCRIPTOR_BINS.csv. Y profiles average all X core points within fixed Y bins; transverse profiles use a ±0.5 mm central Y slice, neither is a tracked toe path.')
 dom=pd.DataFrame(domains).set_index('source_id');n=nsource.groupby('source_id').L2.mean();rho,pvalue=spearmanr(dom.geometry_mean_standardized_distance,n.reindex(dom.index))
 put('GEOMETRIC_DOMAIN_SHIFT.md','Post-hoc geometry shift diagnostics',mdtable(pd.DataFrame(domains))+f'\nSource-level Spearman association of train-standardized mean feature distance with mean-seed L2: rho={rho:.6g}, descriptive p={pvalue:.6g}. Sources share only five documentary plates; this unadjusted p value is not an independent-sample inferential result. OBSERVED_ASSOCIATION only; no causal intervention was tested. Figures 31–32 show range extrapolation and descriptor distance. No observed error changes the frozen models.')
 put('NUMERICAL_TARGET_PRECISION_CONTEXT.md','Numerical reference precision context',mdtable(pd.DataFrame(mesh))+'\n'+mdtable(nsource[['source_id','seed','L2','MAE_MPa']])+'\nM1/M2 differences are conditional two-mesh consistency observations. They are neither a rigorous FE error upper bound nor an attainable-learning-error lower bound. No discrepancy was subtracted from ML error and no guaranteed physical uncertainty interval was calculated.')
 put('INDEPENDENT_LEAKAGE_AUDIT.md','Independent runtime leakage audit',mdtable(pd.DataFrame(rows(R/'INDEPENDENT_LEAKAGE_CHECKS.csv')))+'\nDataset, preprocessing and source/plate runtime membership were separately audited before training and after predictions. The training process denies reading held-out target files and historical checkpoints; inference denies every cached target path and can read only new checkpoints. Runtime membership hashes bind all actual source/plate minibatches to completion receipts. All core masks retain the pretraining support, with no M1/M2 duplicate source, external source, test identity or target-driven crop.')
 put('INDEPENDENT_METRIC_VERIFICATION.md','Independent scalar metric verification','```json\n'+json.dumps(iv,indent=2)+'\n```\nIndependent Python math.fsum scalar reductions and explicit weighted-CDF interpolation reproduce MAE, RMSE, L2, Q95, IoU, regional L2 and equal-plate L2 with absolute tolerance 1e-8 and relative tolerance 1e-10. Arrays compare exact source IDs, XYZ and T0 areas. Prediction coverage and tile counts are checked. This does not independently validate FE physics or experimental stress.')
 put('MODEL_COMPARISON.md','Preregistered model comparison',counts['model_comparison']+'\n\n'+table_study+'\n'+pairtable+'\nNo retrospective practical improvement threshold or favorable seed is introduced. Compare numerical differences on each of five plates. Training fit alone is insufficient evidence of generalization.')
 limitations='Only thirteen sources from five documentary parent plates; E has one source and G five. Plate batches, acquisition sessions, raw scan registration and physical measurement error are unresolved. Frozen V1 targets assume a planar rear at nominal 19 mm, isotropic E=210 GPa and nu=0.30, 100 MPa global X reference tension and specified boundary conditions. No residual stress, plasticity, crack growth, fatigue life or physically validated notch-radius/stress claims. The historical architecture and fixed 80-epoch recipe are tested once; this is not architecture superiority or a capacity-converged training campaign. Finite source sampling, fixed observation window, geometric proxy regions and seed variability remain limitations. Historical external data are exposed and not a fresh blind validation set.'
 put('SCIENTIFIC_LIMITATIONS.md','Scientific limitations',limitations)
 future='Acquire additional independently documented parent plates and production batches, preserve scan sessions/calibration and raw-registration provenance, and provide genuinely blind physical/experimental validation. Next separately authorize a prospectively sealed additional-plate evaluation; any architecture, training-duration, context, feature or observation-window experiment needs a new protocol. Do not tune this study using held-out residual maps or historic exposed tests. No further training is performed in R8-E13.'
 put('FUTURE_EXPERIMENT_DESIGN.md','Future separately authorized research',future)
 put('FINAL_R8E13_DECISION.md','Final scientific and execution decision','```json\n'+json.dumps(counts,indent=2)+'\n```\n\n'+table_study+f'\nWorst observed neural plate: {worst_plate.plate}, seed {worst_plate.seed}, L2={worst_plate.L2:.8f}. Worst neural source: {worst_source.source_id}, seed {worst_source.seed}, L2={worst_source.L2:.8f}.\n\nAdministrative execution completion is distinct from predictive success. The complete scheduled experiment supports only the numerical outcomes under the fixed recipe and documentary-plate split. A practically useful next-generation architecture is not established by this small internal study alone.\n\n'+limitations)
 put('README_REPRODUCIBILITY.md','Reproduction without changing historical work','Runtime: '+pref['python']+'\n\nRead-only checks: `python -B src/verify_release_e13.py` after release. Original training sequence was prepare_e13.py, audit_inputs_e13.py, freeze_e13.py, campaign_e13.py, independent_metrics_e13.py, deliver_e13.py, verify/export checks and release sealing. **Do not rerun completed training or preparation into this workspace.** Reproduction requires a new authorized workspace and exact sealed inputs/code; no ANSYS execution is part of this phase.\n\nPeriodic checkpoints retain model, optimizer, scheduler, RNG, epoch and source memberships. STARTED and COMPLETED files plus recipe/feature/split hashes identify each fit. OOF NPZs preserve all source coordinates and IDs; CSVs contain exact frozen core rows and per-source reference/checkpoint hashes. The release manifest hashes durable artifacts; self-referential seal/receipt exclusions are explicit.')
